// pkg/util/merr/errors.go lines 64-67
// Collection related
ErrCollectionNotFound                      = newMilvusError("collection not found", 100, false)
ErrCollectionNotLoaded                     = newMilvusError("collection not loaded", 101, false)

// pkg/util/merr/utils.go lines 514-520
func WrapErrCollectionNotLoaded(collection any, msg ...string) error {
	err := wrapFields(ErrCollectionNotLoaded, value("collection", collection))
	if len(msg) > 0 {
		err = errors.Wrap(err, strings.Join(msg, "->"))
	}
	return err
}
